argv:
$ErrorActionPreference='Stop';
$keep='831BB6DD8686782FB7C934F7B6DF7D7D';
$close='BDA8B7EBDCC88BDC33081229B15F8978';
$before=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3 | Where-Object {$_.id -in @($keep,$close)});
if($before.Count -ne 2){ throw "expected exact two inspected MCP targets before close" }
Invoke-RestMethod -Uri ('http://127.0.0.1:17410/json/close/'+$close) -TimeoutSec 3 | Out-Null;
Start-Sleep -Milliseconds 300;
$after=@(Invoke-RestMethod -Uri 'http://127.0.0.1:17410/json/list' -TimeoutSec 3 | Where-Object {$_.id -in @($keep,$close)});
[pscustomobject]@{kept=$keep;closed=$close;remaining=@($after|Select-Object id,title,url);count=$after.Count}|ConvertTo-Json -Depth 4 -Compress
